SELECT o.channel, CASE WHEN o.amount >= 1560 THEN 'high' WHEN o.amount >= 350 THEN 'mid' ELSE 'low' END AS amount_bucket, COUNT(DISTINCT oi.unit_price) AS unique_orders FROM order_items oi LEFT JOIN products p ON oi.product_id = p.id LEFT JOIN orders o ON o.id = oi.order_id GROUP BY o.channel, CASE WHEN o.amount >= 1560 THEN 'high' WHEN o.amount >= 350 THEN 'mid' ELSE 'low' END ORDER BY unique_orders;
